/// </summary>
public bool LeaveMatch()
{
    if (_flow == null || _flow.IsAtMain) return false;   // 已在主菜单（无对局/工作台等 dev 落点）：
                                                          // 再请求回 Main 会被流程机拒为"重入禁止"并抛——离场语义不成立，直接 no-op。
    _flow.RequestMain();
    return true;
}

